node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const file = 'ttmp/2026/11/26/IRWB-015--thompson-nfa-regex-matcher/design-doc/01-design-for-a-thompson-nfa-regex-matcher.md';
const doc = readFileSync(file, 'utf8');
const oracle = new Function('pattern', 'text', 'return ' + doc.match(/\`\`\`js\n([^\n]+)\n\`\`\`/)[1]);
const regex = JSON.parse(doc.match(/\`\`\`json\n([\s\S]*?)\n\`\`\`/)[1]).inputs.regexMatch;
const primary = regex.pattern.string;
const cases = [
  [primary, ['d', 'a', 'abbd', 'abb', 'abbe', 'd\n', ''], [1,1,1,1,0,0,0]],
  ['ab|c', ['ab', 'c', 'ac'], [1,1,0]],
  ['[b-d]', ['a', 'b', 'd', 'e'], [0,1,1,0]],
  ['[a-a]*', ['', 'aaa', String.fromCharCode(0)], [1,1,0]],
  ['a*a*a*a*a*a*', ['a'.repeat(12)], [1]],
  [primary, ['a'.repeat(11) + 'd', 'a'.repeat(11) + 'e'], [1,0]],
];
for (const [pattern, texts, results] of cases) {
  assert(pattern.length <= 12 && texts.every(text => text.length <= 12));
  assert.deepEqual(texts.map(text => oracle(pattern, text)), results);
}
assert.equal(primary, '[a-c]*d|ab*');
assert.deepEqual(regex.text, {buffer: [0, 12], cell: [97, 101]});
assert.equal((13 + 13 + 12) * 13, 494);
assert.equal((5 + 2 + 1) * 13 * 4, 416);
console.log('20 RegExp expectations, example metadata, frame sizing and visit bound verified.');
JS
